def maxRunTime(n, batteries):
    lo, hi = 0, sum(batteries) // n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        supply = 0
        for b in batteries:
            supply += b if b < mid else mid
        if supply >= n * mid:
            lo = mid
        else:
            hi = mid - 1
    return lo
